import { Service, ViewContainerRef } from '@angular/core';
import { Observable } from 'rxjs';

@Service()
export class UploadDialogs {
  open(host: ViewContainerRef, progress$: Observable<number>): void {
    const ref = host.createComponent(UploadProgress);
    progress$.subscribe((percent) => {
      ref.instance.percent = percent; // a plain write: nothing is marked
    });
  }
}

import { Service, ViewContainerRef } from '@angular/core';
import { Observable } from 'rxjs';

@Service()
export class UploadDialogs {
  open(host: ViewContainerRef, progress$: Observable<number>): void {
    const ref = host.createComponent(UploadProgress);
    progress$.subscribe((percent) => {
      ref.setInput('percent', percent); // marks the view, schedules a pass
    });
  }
}
